"""Assemble the self-contained asset review pages from the actual SVG files."""
from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'assets/sentinel-ui'
CHECKS=['WIFI_INTERFACE','DRONE_LINK','BATTERY_TELEMETRY','LIVE_VIDEO','LAYOUT_MARKERS','BOUNDED_AREA','HEIGHT_ENVELOPE','EMERGENCY_LATCH']


def svg(path):return (OUT/path).read_text()
def icon(name):return svg('icons/'+name+'.svg').replace('<svg ', '<svg aria-hidden="true" focusable="false" ', 1)
def badge(text,kind='neutral'):return f'<span class="badge {kind}">{escape(text)}</span>'
def heading(n,title,desc):return f'<div class="section-heading"><span class="eyebrow">{n}</span><div><h2>{title}</h2><p>{desc}</p></div></div>'


def build():
    tokens=json.loads((OUT/'tokens/tokens.json').read_text())
    icon_names=sorted(p.stem for p in (OUT/'icons').glob('*.svg'))
    icons=''.join(f'<a class="icon-tile" href="icons/{name}.svg" download>{icon(name)}<span>{name}</span></a>' for name in icon_names)
    swatches=''.join(f'<div class="swatch"><span style="background:{value}"></span><strong>{group}.{name}</strong><code>{value}</code></div>' for group,vals in tokens.items() if group in ['surface','text','accent','status','brand'] for name,value in vals.items())
    sizes=''.join(f'<div class="size-sample"><img src="brand/{"symbol-dark" if size>=40 else "symbol-compact-dark"}.svg" width="{size}" height="{size}" alt="SENTINEL at {size} pixels"><code>{size}px</code></div>' for size in [16,24,32,40,64])
    status_names=['UNSURVEYED','SURVEYING','SURVEYED','HAZARD_PENDING','BLOCKED']
    options=''.join(f'<option>{s}</option>' for s in status_names)
    state_examples=''.join(f'<a href="schematics/examples/{s.lower()}.svg"><img src="schematics/examples/{s.lower()}.svg" alt="All zones {s}"><code>{s}</code></a>' for s in status_names)
    checks=''.join(f'<li><span>{icon("approve")}{name}</span><strong>{"Passed · latch clear" if name=="EMERGENCY_LATCH" else "Passed"}</strong></li>' for name in CHECKS)
    placeholder_cards=''.join(f'<a class="image-card" href="placeholders/{name}.svg" download><img src="placeholders/{name}.svg" alt="{label}"><span>{label}<code>SVG ↓</code></span></a>' for name,label in [('camera-connecting','Camera connecting'),('camera-unavailable','Camera unavailable'),('evidence-empty','Evidence empty'),('evidence-unavailable','Evidence unavailable')])
    groups={
      'Header / source':['Loading','LIVE','SIMULATED','REPLAYED','STALE','Marker mode','Route-only'],
      'Telemetry':['Unavailable','Stale','Low battery · supplied warning'],
      'Operator':['Idle','Submitting','Pending','Rejected','Failed','Emergency disabled'],
      'Approval':['Proposed','Required facts missing','Eligible','Submitting','Approved','Dispatched','Rejected event','Version conflict','Expired','Evidence unavailable','IN_DOUBT','Emergency disabled'],
      'Evidence':['Empty','Loading','Available','NOT_FOUND','FORBIDDEN','Expired / revoked','Stale','IN_DOUBT'],
      'Preflight':['Unknown','Checking','Passed','Failed','Stale report','Ineligible','Emergency disabled'],
      'Video':['STARTING','LIVE','DEGRADED','UNAVAILABLE','STOPPED'],
      'Emergency':['Ordinary','Request pending','Latch acknowledged','Acknowledgement unavailable'],
      'Events':['Empty','Populated','Loading older','Gap / refresh pending','Fault','Emergency','Marker missing']}
    matrix=''.join(f'<details class="state-group"><summary>{name}<span>{len(states)} states</span></summary><div class="badge-list">'+''.join(badge(s) for s in states)+'</div></details>' for name,states in groups.items())
    (OUT/'component-states.json').write_text(json.dumps({'kind':'illustrative-state-inventory','not_wire_fixtures':True,'components':groups},indent=2)+'\n')
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SENTINEL · Interface kit</title><link rel="icon" href="brand/favicon/favicon-dark.svg"><link rel="stylesheet" href="tokens/tokens.css"><link rel="stylesheet" href="review.css"></head>
<body><a class="skip" href="#main">Skip to assets</a><aside class="rail"><a class="brand-symbol" href="#overview" aria-label="SENTINEL"><img src="brand/symbol-dark.svg" width="40" height="40" alt="SENTINEL"></a><div class="rail-title">Interface kit<span>Shared-screen demo / v0</span></div><nav aria-label="Asset sections"><a href="#brand">01 <span>Brand system</span></a><a href="#icons">02 <span>Interface icons</span></a><a href="#schematic">03 <span>Inspection area</span></a><a href="#camera">04 <span>Camera &amp; evidence</span></a><a href="#components">05 <span>Component states</span></a><a href="#tokens">06 <span>Design tokens</span></a></nav><div class="rail-bottom">{badge('REVIEW CANDIDATE')}<p>Real files.<br>Illustrative data.</p><a href="component-specs.md">Component specification ↗</a><a href="manifest.json">Asset manifest ↗</a><a href="README.md">Usage &amp; provenance ↗</a></div></aside>
<main id="main"><header id="overview" class="page-header"><div><div class="eyebrow">SENTINEL / LOCAL ASSET LIBRARY</div><h1>One identity.<br>A complete interface kit.</h1><p>Editable graphics and explicit states for the operator and audience.</p></div><div class="header-actions"><a class="button primary" href="console.html">Open console study ↗</a><span>SVG masters · transparent PNGs · local review</span></div></header>
<div class="notice">{icon('information')}<p>This page is an asset review. Its controls change local examples only; it is not connected to a drone or coordinator.</p></div>
<section id="brand">{heading('01','The SENTINEL identity','Faithful source reconstruction. Symbol only in the operator header.')}<div class="brand-grid"><article class="panel"><div class="card-heading"><h3>Source artwork</h3><span>Supplied JPEG</span></div><div class="brand-stage light"><img src="brand/source/sentinel-logo-original.jpg" alt="User-supplied SENTINEL source logo"></div></article><article class="panel"><div class="card-heading"><h3>Editable reconstruction</h3><span>Outlined SVG</span></div><div class="brand-stage light"><img src="brand/source-aligned-reconstruction.svg" alt="Source-aligned vector reconstruction"></div></article><article class="panel"><div class="card-heading"><h3>Dark surface</h3><span>Transparent SVG</span></div><div class="brand-stage"><img class="trimmed-logo" src="brand/logo-dark.svg" alt="SENTINEL full logo on dark background"></div></article></div>
<div class="panel brand-details"><div><h3>Small sizes, deliberate detail</h3><p>Compact below 40px. Faithful symbol from 40px.</p><div class="size-row">{sizes}</div></div><div class="download-list"><a href="brand/symbol-dark.svg" download>Header symbol / dark SVG ↓</a><a href="brand/symbol-light.svg" download>Header symbol / light SVG ↓</a><a href="brand/logo-dark.svg" download>Complete logo / dark SVG ↓</a><a href="brand/logo-light.svg" download>Complete logo / light SVG ↓</a><a href="brand/favicon/favicon-dark.ico" download>Favicon / ICO ↓</a><a href="brand/provenance.json">Reconstruction provenance ↗</a></div></div><p class="caption">The red center is static branding. Compact variants intentionally simplify the source. Masters remain candidates for your visual acceptance.</p></section>
<section id="icons">{heading('02','A consistent visual vocabulary','14 original icons. 24×24 viewBox. 2px strokes. Inherit currentColor.')}<div class="icon-grid">{icons}</div></section>
<section id="schematic">{heading('03','Six zones. Exact geometry.','Polygon coordinates and zone IDs come directly from the WP0 fixture.')}<div class="schematic-layout"><div class="panel"><div class="card-heading"><h3 id="map-title">Marker mode</h3><span id="freshness-badge" class="badge good">FRESH</span></div><div id="map-host">{svg('schematics/alley-six-zone.svg')}</div><div class="selection-readout" id="selection-readout" aria-live="polite">Select a zone by click, Enter or Space.</div></div><div class="panel inspector"><div class="eyebrow">ILLUSTRATIVE STATE CONTROLS</div><h3>Inspect the treatments</h3><label for="layout-mode">Layout mode</label><select id="layout-mode"><option value="marker">Marker verified</option><option value="route">Route-only · middle zones</option></select><label for="zone-state">Selected zone status</label><select id="zone-state">{options}</select><label class="check"><input id="stale-toggle" type="checkbox"> Snapshot is stale</label><p>Selection is independent of survey status. A stale snapshot keeps its last known state.</p><div id="map-description" class="text-list" aria-live="polite"></div><a href="schematics/alley-six-zone.svg" download>Six-zone SVG ↓</a><a href="schematics/alley-route-only.svg" download>Route-only SVG ↓</a></div></div><div class="state-thumbnails">{state_examples}</div><template id="marker-map-template">{svg('schematics/alley-six-zone.svg')}</template><template id="route-map-template">{svg('schematics/alley-route-only.svg')}</template></section>
<section id="camera">{heading('04','Visible absence. Honest evidence.','Standalone placeholders and overlays, with unavailable values instead of invented detections.')}<div class="placeholder-grid">{placeholder_cards}</div><div class="camera-demo panel"><div class="card-heading"><h3>Overlay treatments</h3><span>Illustrative · not detection evidence</span></div><div class="camera-stage" id="camera-stage"><img class="empty-camera" src="placeholders/camera-unavailable.svg" alt="No current video frame"><div id="marker-example" hidden><img class="marker-box" src="overlays/marker-box.svg" alt="Example marker box"><img class="marker-label" src="overlays/marker-label-example.svg" alt="Illustrative marker label"></div><img id="degraded-example" hidden src="overlays/video-degraded.svg" alt="Video degraded treatment"></div><div class="camera-options"><label class="check"><input type="checkbox" id="marker-toggle"> Show illustrative marker overlay</label><label class="check"><input type="checkbox" id="degraded-toggle"> Show degraded banner</label></div><img class="pose-example" src="overlays/pose-readout-example.svg" alt="Pose unavailable, no fabricated score"></div></section>
<section id="components">{heading('05','States that explain the situation','Presentation samples for review. Operational rules and read-model mappings are in the component specification.')}<div class="component-grid"><article class="panel"><div class="card-heading"><h3>Source and freshness</h3></div><p class="label">Source</p><div class="badge-list">{badge('LIVE','good')}{badge('SIMULATED')}{badge('REPLAYED','warning')}</div><p class="label">Freshness</p><div class="badge-list">{badge('FRESH','good')}{badge('STALE','warning')}</div><p class="label">Outcome</p>{badge('IN_DOUBT','warning')}<hr><h3>Unavailable telemetry</h3><dl class="readings"><div><dt>Battery</dt><dd>— <small>%</small></dd></div><div><dt>Height</dt><dd>— <small>m</small></dd></div><div><dt>Mode</dt><dd class="word">Unknown</dd></div></dl><p>No supported live telemetry source is connected.</p></article>
<article class="panel"><div class="card-heading"><h3>Immutable preflight</h3><span>Illustrative</span></div><ul class="preflight-list">{checks}</ul><p class="caption">A passed latch check means latch clear.</p><label for="preflight-demo">Report treatment</label><select id="preflight-demo"><option value="passed">All checks passed</option><option value="failed">Failed preflight</option><option value="unknown">Checks unavailable</option></select><p id="preflight-message" role="status">Illustrative report passed. Dispatch still requires coordinator eligibility.</p><div id="force-example" hidden><label for="force-reason">Reason for a new run</label><textarea id="force-reason" rows="2" placeholder="Illustrative reason field"></textarea><button disabled>Create new run</button><p class="caption">Requires legal operator action. Never resumes the old run.</p></div></article>
<article class="panel"><div class="card-heading"><h3>Approval and evidence</h3><span>Illustrative</span></div>{badge('PLAN_PROPOSED')}<h3 class="margin-top">Six-zone inspection</h3><p>Review the immutable plan, preflight and evidence before a decision.</p><div class="approval-example"><button disabled>Confirm</button><button disabled>Reject</button></div><p class="caption">Disabled: required coordinator facts are unavailable.</p><details><summary>Required review facts</summary><ul class="plain-list"><li>Plan hash · worker · run binding</li><li>Expiry · expected state version</li><li>Artifact hash · source · selected frame</li><li>Provider · model · prompt/transform revision</li><li>Raw score · semantics · threshold · ranking</li></ul></details><div class="evidence-notice">{icon('information')}<span>No linked hazard<br><small>NOT_FOUND · illustrative state</small></span></div><div class="badge-list">{badge('FORBIDDEN','warning')}{badge('Version conflict','warning')}{badge('Expired','warning')}</div></article></div>
<div class="panel emergency-demo"><div><div class="eyebrow">LOCAL PRESENTATION DEMO</div><h3>Emergency acknowledgement</h3><p>Preview pending and acknowledged states without implying the drone has landed.</p></div><button class="danger" id="emergency-demo-button">{icon('emergency-stop')} EMERGENCY STOP</button><div id="emergency-demo-status" role="alert">Ordinary presentation · Shift+Escape previews a stop request.</div><div class="button-row"><button id="ordinary-demo">Ordinary control example</button><button id="ack-demo" hidden>Preview coordinator acknowledgement</button><button id="reset-emergency">Reset local example</button></div></div>
<div class="panel events-demo"><div class="card-heading"><h3>Recent events</h3><span>Illustrative sequence</span></div><ol class="event-list"><li><time>12:04:01</time><span>Run created</span>{badge('SIMULATED')}</li><li><time>12:04:03</time><span>Preflight reported</span></li><li><time>12:04:05</time><span>Plan proposed · awaiting operator approval</span></li></ol></div><div class="state-matrix">{matrix}</div></section>
<section id="tokens">{heading('06','Tokens, not sampled screenshots','Actual JSON and CSS values shared by the kit. The source logo red remains separate from emergency red.')}<div class="swatch-grid">{swatches}</div><div class="panel type-sheet"><div><span class="eyebrow">MISSION / 32</span><h2>Awaiting operator approval</h2><p>Body / 16px — Review the plan before dispatch.</p><small>Metadata / 14px — Updated at 12:04:05</small><p><code>RUN · EXAMPLE-001 / STATE · 42</code></p></div><div><h3>Spacing &amp; shape</h3><p>4 · 8 · 12 · 16 · 24 · 32 · 48 px</p><p>8px panel radius · 2px icon stroke</p><a href="tokens/tokens.json" download>Token JSON ↓</a><br><a href="tokens/tokens.css" download>CSS variables ↓</a></div></div></section><footer>Built from your supplied logo and the WP0 fixture. <a href="README.md">Usage notes</a> · <a href="validation.json">Validation report</a></footer></main><script src="review.js"></script></body></html>'''
    (OUT/'review.html').write_text(doc)
    console=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SENTINEL · Console study</title><link rel="icon" href="brand/favicon/favicon-dark.svg"><link rel="stylesheet" href="tokens/tokens.css"><link rel="stylesheet" href="review.css"></head><body class="console-page"><div class="console-shell"><header data-testid="Header" class="console-header"><a href="review.html" aria-label="SENTINEL asset review"><img src="brand/symbol-dark.svg" width="40" height="40" alt="SENTINEL"></a><div class="run-meta"><strong>Indoor alley inspection</strong><span>EXAMPLE-001 · state 42</span></div><div class="badge-list">{badge('SIMULATED')}{badge('FRESH','good')}{badge('Marker mode')}</div><button class="danger" id="console-emergency">{icon('emergency-stop')} EMERGENCY STOP</button></header>
<aside data-testid="Left" class="panel console-left"><div class="eyebrow">OPERATOR</div><h2>Mission intent</h2><div class="chat-bubble"><span>Operator</span><p>Inspect the six alley zones.</p></div><div class="chat-bubble answer"><span>SENTINEL</span><p>Catalogue plan ready for review.</p></div><ul class="activity-list"><li>{icon('approve')} Intent received</li><li>{icon('approve')} Plan prepared</li><li>{icon('clock')} Awaiting approval</li></ul><label for="console-intent">Operator message</label><textarea id="console-intent" rows="3" disabled placeholder="Static composition study"></textarea><small>Illustrative data. No coordinator connection.</small></aside>
<section data-testid="Center" class="console-center"><div class="mission-heading"><div class="eyebrow">CURRENT MISSION</div><h1>Awaiting operator approval</h1><p>Review the plan before dispatch.</p></div><div class="panel console-map">{svg('schematics/alley-six-zone.svg')}</div><div class="panel console-camera"><div class="card-heading"><h3>Camera</h3>{badge('UNAVAILABLE','warning')}</div><img src="placeholders/camera-unavailable.svg" alt="No current camera frame"></div></section>
<aside data-testid="Right" class="console-right"><div class="panel"><div class="eyebrow">DRONE STATUS</div><dl class="readings"><div><dt>Battery</dt><dd>— <small>%</small></dd></div><div><dt>Mode</dt><dd class="word">Unknown</dd></div></dl><small>No telemetry source connected</small></div><div class="panel"><div class="eyebrow">PLAN APPROVAL</div><h3>Six-zone inspection</h3>{badge('PLAN_PROPOSED')}<p>Required facts unavailable.</p><div class="approval-example"><button disabled>Confirm</button><button disabled>Reject</button></div><details><summary>Review requirements</summary><p>Plan hash, binding, expiry, preflight, evidence and state version.</p></details></div><div class="panel"><div class="eyebrow">PREFLIGHT</div><p>8 required checks</p>{badge('Unknown','warning')}<small>Report not connected</small></div><div class="panel"><div class="eyebrow">EVIDENCE</div><h3>No linked hazard</h3><p>Capture and provenance unavailable.</p></div></aside>
<footer data-testid="Bottom" class="panel console-bottom"><div class="event-strip"><span><time>12:04:01</time> Run created</span><span><time>12:04:03</time> Plan prepared</span><span><time>12:04:05</time> Awaiting approval</span></div><div id="console-notice" role="alert">COMPOSITION STUDY · ILLUSTRATIVE DATA · No drone commands · Shift+Escape previews emergency pending</div></footer></div><script src="console.js"></script></body></html>'''
    (OUT/'console.html').write_text(console)
    print('Built local review and 1440×900 console study from actual assets.')


if __name__=='__main__':build()
